import { constants } from "node:fs";
import { lstat, mkdir, open, realpath, stat } from "node:fs/promises";
import { homedir, tmpdir } from "node:os";
import { basename, dirname, parse, resolve, sep } from "node:path";

export type WorkspaceErrorCode =
  | "WORKSPACE_TRAVERSAL"
  | "WORKSPACE_ESCAPE"
  | "WORKSPACE_UNSAFE_ROOT"
  | "WORKSPACE_NOT_DIRECTORY"
  | "WORKSPACE_SPECIAL_FILE"
  | "STATIC_FILE_UNSAFE";

export class WorkspacePolicyError extends Error {
  constructor(readonly code: WorkspaceErrorCode, message: string) {
    super(message);
    this.name = "WorkspacePolicyError";
  }
}

const broadRoots = new Set([
  "/",
  "/bin",
  "/boot",
  "/dev",
  "/etc",
  "/home",
  "/lib",
  "/lib64",
  "/media",
  "/mnt",
  "/opt",
  "/proc",
  "/root",
  "/run",
  "/sbin",
  "/srv",
  "/sys",
  "/tmp",
  "/usr",
  "/var",
  "/var/data",
  "/var/log",
  "/var/tmp",
  "/Users",
  "/Volumes",
  "/private",
  "/System",
]);

function normalized(path: string): string {
  return resolve(path).replace(/[\\/]+$/, "") || sep;
}

function isInside(root: string, candidate: string): boolean {
  return candidate === root || candidate.startsWith(`${root}${sep}`);
}

export function assertNotBroadRoot(path: string): void {
  const resolved = normalized(path);
  const home = normalized(homedir());
  const temporary = normalized(tmpdir());
  const repository = normalized(process.cwd());
  const filesystemRoot = parse(resolved).root;

  if (
    resolved === filesystemRoot
    || broadRoots.has(resolved)
    || resolved === home
    || resolved === temporary
    || resolved === repository
    || resolved === normalized(dirname(home))
  ) {
    throw new WorkspacePolicyError(
      "WORKSPACE_UNSAFE_ROOT",
      "The configured workspace is a filesystem, home, temporary, or repository root. Choose a dedicated child directory.",
    );
  }
}

export interface CanonicalRoot {
  requested: string;
  real: string;
  device: number;
  inode: number;
}

export async function canonicalizeDirectoryRoot(path: string, options?: { allowedParent?: string; create?: boolean }): Promise<CanonicalRoot> {
  const requested = resolve(path);
  assertNotBroadRoot(requested);
  if (options?.create !== false) await mkdir(requested, { recursive: true, mode: 0o700 });
  await assertNotSymlinkEscape(requested, options?.allowedParent);
  const real = await realpath(requested);
  assertNotBroadRoot(real);
  const info = await lstat(real);
  if (!info.isDirectory()) {
    throw new WorkspacePolicyError("WORKSPACE_NOT_DIRECTORY", `Workspace ${basename(real)} is not a directory.`);
  }
  if (!Number.isSafeInteger(info.dev) || !Number.isSafeInteger(info.ino)) {
    throw new WorkspacePolicyError("WORKSPACE_SPECIAL_FILE", "Workspace identity could not be established.");
  }
  return { requested, real, device: info.dev, inode: info.ino };
}

async function assertNotSymlinkEscape(path: string, allowedParent: string | undefined): Promise<void> {
  if (!allowedParent) return;
  const realParent = await realpath(resolve(allowedParent));
  const realChild = await realpath(path);
  if (realChild !== realParent && !isInside(realParent, realChild)) {
    throw new WorkspacePolicyError("WORKSPACE_ESCAPE", "The workspace symlink resolves outside its allowed data directory.");
  }
}

export async function assertWorkspaceContains(root: string, candidate: string): Promise<string> {
  const realRoot = await realpath(resolve(root));
  const realCandidate = await realpath(resolve(candidate));
  if (realCandidate !== realRoot && !isInside(realRoot, realCandidate)) {
    throw new WorkspacePolicyError("WORKSPACE_ESCAPE", "The workspace path resolves outside its canonical root.");
  }
  return realCandidate;
}


export async function assertRegularFile(path: string, options?: { allowMissing?: boolean }): Promise<void> {
  let info;
  try {
    info = await lstat(path);
  } catch (error) {
    if (options?.allowMissing && (error as NodeJS.ErrnoException).code === "ENOENT") return;
    throw error;
  }
  if (info.isSymbolicLink()) {
    throw new WorkspacePolicyError("STATIC_FILE_UNSAFE", "A symbolic link cannot be used for persisted state.");
  }
  if (!info.isFile()) {
    throw new WorkspacePolicyError("STATIC_FILE_UNSAFE", "Only regular files are permitted.");
  }
}

export function assertSafeRelativePath(path: string): string {
  if (path.includes("\0")) {
    throw new WorkspacePolicyError("WORKSPACE_TRAVERSAL", "A request path contained a null byte.");
  }
  const withoutLeading = path.replace(/^\/+/, "");
  if (withoutLeading.length === 0) return "index.html";
  if (withoutLeading.split(/[\\/]+/).some((part) => part === "..")) {
    throw new WorkspacePolicyError("WORKSPACE_TRAVERSAL", "A request path attempted directory traversal.");
  }
  return withoutLeading;
}

export async function resolveStaticFile(root: string, requestPath: string): Promise<string | null> {
  const relative = assertSafeRelativePath(requestPath);
  const realRoot = await realpath(resolve(root));
  const requested = resolve(realRoot, relative);
  if (!isInside(realRoot, requested)) {
    throw new WorkspacePolicyError("WORKSPACE_TRAVERSAL", "The static file request escaped the web root.");
  }
  let realRequested: string;
  try {
    realRequested = await realpath(requested);
  } catch {
    return null;
  }
  if (!isInside(realRoot, realRequested)) {
    throw new WorkspacePolicyError("WORKSPACE_ESCAPE", "A static file symlink escaped the web root.");
  }
  const info = await stat(realRequested);
  if (!info.isFile()) return null;
  return realRequested;
}

export async function ensurePrivateDirectory(path: string): Promise<void> {
  await mkdir(path, { recursive: true, mode: 0o700 });
  const info = await lstat(path);
  if (!info.isDirectory()) {
    throw new WorkspacePolicyError("WORKSPACE_NOT_DIRECTORY", "The state directory could not be created.");
  }
}

export async function writePrivateBytes(path: string, data: Uint8Array | string): Promise<void> {
  const handle = await open(path, constants.O_WRONLY | constants.O_CREAT | constants.O_EXCL, 0o600);
  try {
    await handle.writeFile(data, typeof data === "string" ? "utf8" : undefined);
    await handle.sync();
  } finally {
    await handle.close();
  }
}

export async function writePrivateFile(path: string, data: string): Promise<void> {
  await writePrivateBytes(path, data);
}

#!/usr/bin/env node
// Diagnostic only: no inference, installs, account setup, or Git mutations.
import { execFile } from 'node:child_process';
import { constants } from 'node:fs';
import { access, mkdtemp, readFile, rm } from 'node:fs/promises';
import { Resolver } from 'node:dns/promises';
import { createServer } from 'node:net';
import { tmpdir } from 'node:os';
import { delimiter, dirname, join, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';
import { promisify } from 'node:util';

const execute = promisify(execFile);
const workspace = resolve(dirname(fileURLToPath(import.meta.url)), '..');
const findings = [];

function record(id, status, detail) {
  findings.push({ id, status, detail });
}

async function command(binary, args, env = process.env) {
  try {
    const result = await execute(binary, args, {
      cwd: workspace, env, timeout: 15_000, maxBuffer: 256 * 1024,
    });
    return { ok: true, output: result.stdout.trim() };
  } catch (error) {
    // Do not echo raw command output: providers/plugins may print secrets.
    return { ok: false, code: error.killed ? 'TIMEOUT' : String(error.code ?? 'UNKNOWN') };
  }
}

async function locate(name) {
  for (const directory of (process.env.PATH ?? '').split(delimiter)) {
    if (!directory) continue;
    const candidate = join(directory, name);
    try {
      await access(candidate, constants.X_OK);
      return candidate;
    } catch { /* Try the next PATH entry. */ }
  }
  return null;
}

async function inspectOpenCode() {
  const binary = await locate('opencode');
  if (!binary) {
    record('OPENCODE_CLI', 'FAIL', 'OpenCode is absent from PATH.');
    return;
  }
  const temporary = await mkdtemp(join(tmpdir(), 'ub-preflight-'));
  try {
    // Supported disposable XDG storage avoids changing the user's sessions/auth.
    const env = {
      ...process.env,
      XDG_DATA_HOME: join(temporary, 'data'),
      XDG_CACHE_HOME: join(temporary, 'cache'),
      XDG_STATE_HOME: join(temporary, 'state'),
    };
    const version = await command(binary, ['--version'], env);
    const match = version.ok && version.output.match(/^opencode v?(\d+\.\d+\.\d+)(?:\s|$)/);
    record('OPENCODE_CLI', match ? 'PASS' : 'INCONCLUSIVE', match
      ? `Installed binary ${match[1]}; CLI startup only, not server/model proof.`
      : 'Could not identify the binary version within 15 seconds.');
    const help = await command(binary, ['serve', '--help'], env);
    record('OPENCODE_SERVER_COMMAND', help.ok && /--hostname/.test(help.output) ? 'PASS' : 'INCONCLUSIVE',
      'Inspects serve help only; no server or session was started.');
    try {
      const adjacent = join(dirname(dirname(binary)), 'node_modules', '@opencode-ai', 'sdk', 'package.json');
      const sdk = JSON.parse(await readFile(adjacent, 'utf8'));
      record('SDK_COMPATIBILITY', 'INCONCLUSIVE',
        `Adjacent @opencode-ai/sdk ${sdk.version}; compatibility has not been exercised. Check the native v2 @opencode/client contract.`);
    } catch {
      record('SDK_COMPATIBILITY', 'NOT_RUN', 'No adjacent legacy SDK metadata found; select the supported version-matched client during EP-01.');
    }
  } finally {
    await rm(temporary, { recursive: true, force: true });
  }
}

async function inspectNetwork(host) {
  const resolver = new Resolver({ timeout: 1500, tries: 1 });
  try {
    await resolver.resolve4(host);
    record(`DNS:${host}`, 'PASS', 'DNS resolves; HTTPS and authenticated/free inference remain unproven.');
  } catch (error) {
    record(`DNS:${host}`, 'FAIL', `DNS unavailable (${error.code ?? 'UNKNOWN'}).`);
  } finally {
    resolver.cancel();
  }
}

async function inspectLoopback() {
  await new Promise((done) => {
    const server = createServer();
    let completed = false;
    const finish = (status, detail) => {
      if (completed) return;
      completed = true;
      clearTimeout(timer);
      record('LOOPBACK_BIND', status, detail);
      done();
    };
    const timer = setTimeout(() => {
      server.close(() => {});
      finish('INCONCLUSIVE', 'Temporary localhost bind exceeded the two-second diagnostic bound.');
    }, 2000);
    server.once('error', (error) => finish('FAIL', `Cannot bind localhost (${error.code ?? 'UNKNOWN'}); native server proof cannot run here.`));
    server.listen(0, '127.0.0.1', () => {
      server.close(() => finish('PASS', 'Temporary localhost listener opened and closed; no requests, model calls or application server.'));
    });
  });
}

async function inspectRepository() {
  const branch = await command('git', ['branch', '--show-current']);
  const head = await command('git', ['rev-parse', '--short', 'HEAD']);
  record('GIT_READ', branch.ok && head.ok ? 'PASS' : 'FAIL', branch.ok && head.ok
    ? `Branch ${branch.output}, HEAD ${head.output}; no index/worktree mutations.`
    : 'Cannot read current branch/HEAD.');
  record('GIT_WRITE', 'NOT_RUN', 'No Git write probe. The agent session must separately permit .git writes before a phase commit.');
}

async function inspectEntire() {
  const binary = await locate('entire');
  if (!binary) {
    record('ENTIRE_CAPTURE', 'FAIL', 'Entire is absent from PATH.');
    return;
  }
  const result = await command(binary, ['status']);
  if (result.ok && /not set up|not enabled|disabled/i.test(result.output)) {
    record('ENTIRE_CAPTURE', 'FAIL', 'Entire reports capture is not enabled; no setup was performed.');
  } else if (result.ok && /hooks?[^\n]*need approval/i.test(result.output)) {
    record('ENTIRE_CAPTURE', 'FAIL', 'Entire is enabled, but agent hooks need approval. Open /hooks in the local Codex session, approve the Entire hooks, then verify capture.');
  } else {
    record('ENTIRE_CAPTURE', 'INCONCLUSIVE', 'Verify capture, sharing settings, supported agent and checkpoint evidence separately.');
  }
}

const [major, minor] = process.versions.node.split('.').map(Number);
record('NODE', major > 22 || (major === 22 && minor >= 14) ? 'PASS' : 'FAIL', process.version);
const tasks = await Promise.allSettled([
  inspectOpenCode(), inspectRepository(), inspectEntire(),
  inspectNetwork('opencode.ai'), inspectNetwork('registry.npmjs.org'), inspectLoopback(),
]);
for (const [index, result] of tasks.entries()) {
  if (result.status === 'rejected') record(`DIAGNOSTIC:${index}`, 'INCONCLUSIVE', 'Diagnostic failed; inspect the environment without exposing credentials.');
}
for (const name of ['SENTRY_DSN', 'BACKBOARD_API_KEY', 'OPENCODE_BASE_URL']) {
  record(`ENV:${name}`, 'INFO', process.env[name] ? 'present (value withheld)' : 'absent from this process; other supported configuration locations not inspected');
}
for (const proof of ['EP-01_FREE_MODEL_AND_EDIT', 'EP-02_NATIVE_PERMISSIONS', 'EP-03_RECOVERY', 'EP-04_BACKBOARD', 'EP-05_SENTRY', 'EP-06_ENTIRE_CHECKPOINT']) {
  record(proof, 'NOT_RUN', 'A diagnostic cannot establish this runtime proof.');
}
findings.sort((a, b) => a.id.localeCompare(b.id));
const blocked = findings.some(({ status }) => status === 'FAIL');
console.log(JSON.stringify({
  status: blocked ? 'BLOCKED' : 'PREFLIGHT_ONLY',
  workspace, findings,
  limits: 'No inference, dependency installation, authentication changes, application server startup, capture setup, or Git writes. A temporary localhost listener is immediately closed. PASS refers only to the named diagnostic.',
}, null, 2));
process.exitCode = blocked ? 1 : 0;
import { mkdtemp, rm } from "node:fs/promises";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { ConnectionService } from "../src/server/opencode/connection.ts";
import { createNativeClient, redactSecrets } from "../src/server/opencode/client.ts";

const enabled = process.env.OPENCODE_LIVE_DIAGNOSTIC === "1";
if (!enabled) {
  console.log(JSON.stringify({
    status: "SKIP",
    message: "Set OPENCODE_LIVE_DIAGNOSTIC=1 to connect to a running OpenCode server. This script performs no model inference.",
  }, null, 2));
  process.exit(0);
}

const baseUrl = process.env.OPENCODE_BASE_URL?.trim() || "http://127.0.0.1:4096";
const REDACTED = REDACTED;
const username = process.env.OPENCODE_USERNAME?.trim() || "opencode";
const dataDir = await mkdtemp(join(tmpdir(), "ub-live-"));
const workspace = join(dataDir, "workspace");
await import("node:fs/promises").then(({ mkdir }) => mkdir(workspace, { recursive: true }));

try {
  const connection = new ConnectionService({
    dataDir,
    deploymentMode: "local",
    envBaseUrl: baseUrl,
    envUsername: username,
    envPassword: REDACTED,
  });
  await connection.load();
  const status = await connection.check();
  const discovery = status.discovery;
  let sessionApi: { available: boolean; detail: string } = { available: false, detail: "Discovery did not complete." };
  if (discovery) {
    const available = discovery.models.find((model) => model.availability === "available");
    if (!available) {
      sessionApi = { available: false, detail: "No available model exists for a harmless session create/get/remove check." };
    } else {
      try {
        const client = createNativeClient({ baseUrl, username, REDACTED });
        const created = await client.session.create({
          title: "Unfinished Business compatibility probe",
          location: { directory: workspace },
          model: { providerID: available.providerID, id: available.id },
        });
        const fetched = await client.session.get({ sessionID: created.id });
        await client.session.remove({ sessionID: created.id });
        sessionApi = {
          available: fetched.id === created.id,
          detail: "Created, read, and removed a disposable empty session. No prompt was sent and no model was called.",
        };
      } catch (error) {
        sessionApi = {
          available: false,
          detail: redactSecrets(error instanceof Error ? error.message : "Session API check failed."),
        };
      }
    }
  }
  console.log(JSON.stringify({
    status: status.state === "connected" || status.state === "degraded" ? "COMPATIBLE" : "BLOCKED",
    state: status.state,
    serverVersion: status.serverVersion,
    testedVersion: discovery?.server.testedVersion ?? null,
    compatibleMajor: discovery?.server.compatible ?? false,
    baseUrl,
    REDACTEDSupplied: Boolean(REDACTED),
    counts: {
      providers: discovery?.providers.length ?? 0,
      models: discovery?.models.length ?? 0,
      agents: discovery?.agents.length ?? 0,
      commands: discovery?.commands.length ?? 0,
      skills: discovery?.skills.length ?? 0,
      mcpServers: discovery?.mcpServers.length ?? 0,
    },
    sessionApi,
    diagnostics: status.diagnostics,
    limitations: discovery?.limitations ?? [],
    note: "No prompt, model call, provider credential read, or project write occurred.",
  }, null, 2));
  process.exitCode = sessionApi.available || status.state === "degraded" ? 0 : status.state === "connected" ? 0 : 1;
} catch (error) {
  console.error(JSON.stringify({
    status: "BLOCKED",
    message: redactSecrets(error instanceof Error ? error.message : String(error)),
  }, null, 2));
  process.exitCode = 1;
} finally {
  await rm(dataDir, { recursive: true, force: true });
}
